import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';
const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });
const heartbeat = () => db.prepare('INSERT INTO worker_health VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET heartbeat = excluded.heartbeat').run(Date.now());
heartbeat();
const timer = setInterval(heartbeat, 500);
// With one worker process, all running jobs at startup belong to an interrupted attempt.
db.prepare(\"UPDATE jobs SET status = 'queued', availableAt = 0, updatedAt = ? WHERE status = 'running'\").run(new Date().toISOString());
console.log('worker started');
try {
  while ("'!stopping) {
    const job = db.prepare(`UPDATE jobs SET status = '"'running', attempts = attempts + 1, completed = 0, output = NULL, error = NULL, updatedAt = ?
      WHERE id = (SELECT id FROM jobs WHERE status = 'queued' AND availableAt <= ? ORDER BY rowid LIMIT 1) RETURNING *"'`).get(new Date().toISOString(), Date.now()) as unknown as JobRow | undefined;
    if (!job) { await sleep(100); continue; }
    for (let step = 1; step <= job.steps; step++) {
      await sleep(100);
      if (stopping) break;
      const now = new Date().toISOString();
      if (job.attempts <= job.failAttempts) {
        db.prepare('"'UPDATE jobs SET status = ?, error = ?, availableAt = ?, updatedAt = ? WHERE id = ?').run(
          job.attempts >= 3 ? 'failed' : 'queued', job.attempts >= 3 ? 'transient failure' : null, Date.now() + 400, now, job.id);
        break;
      }
      db.prepare('UPDATE jobs SET completed = ?, status = ?, output = ?, updatedAt = ? WHERE id = ?').run(
        step, step === job.steps ? 'completed' : 'running', step === job.steps ? job.input.toUpperCase() : null, now, job.id);
    }
  }
} finally {
  clearInterval(timer);
  db.prepare('DELETE FROM worker_health WHERE id = 1').run();
  db.close();
}
EOF"

